// ---- 1. which rows are foreign charges, and which exchange rates are needed? -----------------------------------
// rows = FX-statement-tab rows, cfg = { base_currency, date_col, merchant_col, billed_col, foreign_col, currency_col, fx_api, lookback_days }
function planRates(rows, cfg) {
  const base = String(cfg.base_currency || 'JPY').toUpperCase();
  const parsed = [];
  let skipped = 0;
  const seen = new Map();
  rows.forEach((r, i) => {
    const cur = nfkc(r[cfg.currency_col]).trim().toUpperCase();
    if (!cur || cur === base) { skipped++; return; } // a domestic charge
    const date = parseDate(r[cfg.date_col]);
    const merchant = String(r[cfg.merchant_col] ?? '').trim();
    const billed = parseAmount(r[cfg.billed_col]);
    const foreign = parseAmount(r[cfg.foreign_col]);
    const k = date + '|' + merchant + '|' + billed + '|' + foreign + '|' + cur;
    const n = (seen.get(k) ?? 0) + 1; seen.set(k, n);
    parsed.push({ row_key: 'fx-' + hash(k) + '#' + n, row: i + 2, date, merchant, currency: cur, foreign, billed });
  });
  const lookback = Number(cfg.lookback_days) || 7;
  const byCur = new Map();
  for (const p of parsed) {
    if (!p.date || !/^[A-Z]{3}$/.test(p.currency)) continue;
    const e = byCur.get(p.currency) ?? { from: p.date, to: p.date };
    if (p.date < e.from) e.from = p.date;
    if (p.date > e.to) e.to = p.date;
    byCur.set(p.currency, e);
  }
  const currencies = [...byCur.entries()].map(([currency, e]) => {
    const from = fromDayNo(dayNo(e.from) - lookback);
    return { currency, from, to: e.to, url: cfg.fx_api + '/' + from + '..' + e.to + '?base=' + currency + '&symbols=' + base };
  });
  return { parsed, currencies, skipped };
}

// the newest rate on or before the date, at most lookback days back (weekends and bank holidays have no rate)
function rateFor(series, date, lookback) {
  if (!series?.rates) return null;
  let best = null;
  for (const d of Object.keys(series.rates)) if (d <= date && dayNo(date) - dayNo(d) <= lookback && (!best || d > best)) best = d;
  const v = best ? series.rates[best]?.[Object.keys(series.rates[best])[0]] : null;
  return best && Number.isFinite(Number(v)) ? { date: best, rate: Number(v) } : null;
}

