  const checkedAt = cfg.now;
  return plan.parsed.map((p) => {
    const row = { row_key: p.row_key, date: p.date, merchant: p.merchant, currency: p.currency, foreign_amount: Number.isFinite(p.foreign) ? p.foreign : '', billed: Number.isFinite(p.billed) ? p.billed : '',
      rate_date: '', market_rate: '', expected_billed: '', effective_rate: '', premium_pct: '', extra: '', status: '', note: '', checked_at: checkedAt };
    if (!p.date) { row.status = 'Check data'; row.note = 'row ' + p.row + ': the date could not be read (year first, like 2026-09-05)'; return row; }
    if (!(p.foreign > 0) || !(p.billed > 0)) { row.status = 'Check data'; row.note = 'row ' + p.row + ': the foreign amount and the billed amount must both be positive numbers'; return row; }
    row.effective_rate = Math.round((p.billed / p.foreign) * 1000) / 1000;
    const hit = rateFor(seriesBy[p.currency], p.date, lookback);
    if (!hit) { row.status = 'Rate unavailable'; row.note = 'no ' + p.currency + '/' + base + ' rate within ' + lookback + ' days before ' + p.date + ' (the API may not support ' + p.currency + ')'; return row; }
    const expected = p.foreign * hit.rate;
    const premium = (p.billed / expected - 1) * 100;
    row.rate_date = hit.date; row.market_rate = hit.rate; row.expected_billed = Math.round(expected * 100) / 100;
    row.premium_pct = Math.round(premium * 100) / 100; row.extra = Math.round((p.billed - expected) * 100) / 100;
    if (premium > warn) { row.status = 'High premium'; row.note = 'billed ' + row.premium_pct + '% above the market rate (limit ' + warn + '%)'; }
    else if (premium < low) { row.status = 'Below market'; row.note = 'billed ' + Math.abs(row.premium_pct) + '% below the market rate: check the amounts or the currency'; }
    else row.status = 'OK';
    if (hit.date !== p.date) row.note = (row.note ? row.note + '; ' : '') + 'rate of ' + hit.date + ' used (no rate on ' + p.date + ')';
    return row;
  });
}

function summarize(rows, base, skipped) {
  const count = {};
  for (const r of rows) count[r.status] = (count[r.status] ?? 0) + 1;
  const priced = rows.filter((r) => r.extra !== '');
  const totalExtra = priced.reduce((s, r) => s + r.extra, 0);
  const total = priced.reduce((s, r) => s + r.billed, 0);
  const worst = rows.filter((r) => r.status === 'High premium').sort((a, b) => b.extra - a.extra).slice(0, 5);
  const head = '*Foreign-currency charges* - ' + Object.entries(count).map(([k, v]) => k + ': ' + v).join(', ') + (skipped ? ' (' + skipped + ' ' + base + ' rows skipped)' : '');
  const money = '\nBilled ' + Math.round(total) + ' ' + base + ' on ' + priced.length + ' charges; ' + (totalExtra >= 0 ? Math.round(totalExtra) + ' ' + base + ' above' : Math.round(-totalExtra) + ' ' + base + ' below') + ' the market rate in total (ECB reference rates, a yardstick, not the card network rate).';
  const lines = worst.map((r) => '• ' + r.date + ' ' + r.merchant + ' ' + r.foreign_amount + ' ' + r.currency + ' -> ' + r.billed + ' ' + base + ' (+' + r.premium_pct + '%, ' + Math.round(r.extra) + ' ' + base + ')');
  const flagged = rows.filter((r) => ['Check data', 'Rate unavailable', 'Below market'].includes(r.status)).slice(0, 5).map((r) => '• ' + r.status + ': ' + r.date + ' ' + r.merchant + ' - ' + r.note);
  return [head + money, lines.length ? '*Highest premiums*\n' + lines.join('\n') : '', flagged.length ? '*Look at these*\n' + flagged.join('\n') : ''].filter(Boolean).join('\n');
}

const cfg = $('Config').first().json;
const rows = $('Check charges').all().map((i) => i.json).filter((r) => r.row_key !== 'none');
const skipped = $('Plan rates').all()[0]?.json?.skipped ?? 0;
return [{ json: { text: summarize(rows, String(cfg.base_currency || 'JPY').toUpperCase(), skipped) } }];
